_PROCESS_RUNTIME_CAPABILITY_EPOCH = secrets.token_hex(16)
_PROCESS_RUNTIME_HANDOFF_LOCK = threading.RLock()
_PROCESS_RUNTIME_HANDOFFS: weakref.WeakValueDictionary[tuple[str, str], Runtime] = weakref.WeakValueDictionary()


def _runtime_server_instance_id(runtime: object) -> str | None:
    value = getattr(runtime, "server_instance_id", None)
    return value if isinstance(value, str) and value else None


def _register_process_runtime_handoff(
    capability_epoch: str,
    process_session_id: str,
    runtime: Runtime,
) -> bool:
    """Keep a non-authoritative in-process handle for the upstream session.

    SQLite owns the durable identity and all approval checks.  This bounded
    weak map only bridges two logical WrapperRuntime objects in the same
    physical process because coding-tools-mcp keeps Popen/session state on its
    Runtime instance and deliberately has no durable process registry.
    """

    key = (capability_epoch, process_session_id)
    with _PROCESS_RUNTIME_HANDOFF_LOCK:
        current = _PROCESS_RUNTIME_HANDOFFS.get(key)
        if current is not None and current is not runtime:
            return False
        _PROCESS_RUNTIME_HANDOFFS[key] = runtime
        return True


def _lookup_process_runtime_handoff(
    capability_epoch: str,
    process_session_id: str,
    upstream_runtime_id: str,
) -> Runtime | None:
    key = (capability_epoch, process_session_id)
    with _PROCESS_RUNTIME_HANDOFF_LOCK:
        runtime = _PROCESS_RUNTIME_HANDOFFS.get(key)
        if runtime is None or _runtime_server_instance_id(runtime) != upstream_runtime_id:
            return None
        return runtime


def _unregister_process_runtime_handoff(
    capability_epoch: str,
    process_session_id: str,
    runtime: Runtime | None = None,
) -> None:
    key = (capability_epoch, process_session_id)
    with _PROCESS_RUNTIME_HANDOFF_LOCK:
        current = _PROCESS_RUNTIME_HANDOFFS.get(key)
        if current is not None and (runtime is None or current is runtime):
            _PROCESS_RUNTIME_HANDOFFS.pop(key, None)


def _unregister_runtime_process_handoffs(runtime: Runtime) -> None:
    with _PROCESS_RUNTIME_HANDOFF_LOCK:
        for key, current in tuple(_PROCESS_RUNTIME_HANDOFFS.items()):
            if current is runtime:
                _PROCESS_RUNTIME_HANDOFFS.pop(key, None)


