def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _session_counts_toward_parallel_limit(session: DevelopmentSession, now: float) -> bool:
    if session.stale or session.is_expired(now):
        return False
    return session.lifecycle_state not in {
        DevelopmentSessionStatus.INTEGRATED.value,
        DevelopmentSessionStatus.CLEANUP_CANDIDATE.value,
        DevelopmentSessionStatus.CLOSED.value,
    }


def _tool_schema_metadata(
    definitions: list[dict[str, Any]],
    *,
    revision: str = TOOL_SCHEMA_REVISION,
) -> dict[str, Any]:
    return tool_schema_metadata(definitions, revision=revision)


