@dataclass(frozen=True)
class LinkedWorktreeSnapshot:
    """Pinned identity and content evidence for one linked Git worktree.

    A canonical checkout move changes only the Git metadata backlink held in
    the linked worktree's ``.git`` file.  Everything else is evidence that the
    relocation transaction must preserve byte-for-byte (or, for Git status,
    by the exact bounded command digest).
    """

    path: Path
    worktree_id: str
    head: str
    branch: str
    detached: bool
    device: int
    inode: int
    dirty: bool
    status_hash: str
    tracked_patch_hash: str
    index_hash: str
    untracked_manifest_hash: str
    untracked_manifest: tuple[dict[str, Any], ...]
    gitfile_target: Path
    common_dir: Path
    admin_dir: Path
    admin_device: int
    admin_inode: int

    def as_dict(self) -> dict[str, Any]:
        """Return sanitized preflight evidence without exposing file bytes."""

        return {
            "path": str(self.path),
            "worktree_id": self.worktree_id,
            "head": self.head,
            "branch": self.branch,
            "detached": self.detached,
            "device": self.device,
            "inode": self.inode,
            "dirty": self.dirty,
            "status_hash": self.status_hash,
            "tracked_patch_hash": self.tracked_patch_hash,
            "index_hash": self.index_hash,
            "untracked_manifest_hash": self.untracked_manifest_hash,
            "untracked_manifest": [dict(item) for item in self.untracked_manifest],
            "gitfile_target": str(self.gitfile_target),
            "common_dir": str(self.common_dir),
            "admin_dir": str(self.admin_dir),
            "admin_device": self.admin_device,
            "admin_inode": self.admin_inode,
        }


def _config_path() -> Path:
    raw = os.environ.get("LOCAL_DEV_MCP_CONFIG")
    if raw:
        return Path(raw).expanduser()
    return Path.home() / ".config" / "local-dev-mcp" / "config.json"


def _director_db_path_for_runtime(config_path: Path) -> Path:
    """Resolve the internal Director DB without exposing a caller path.

    Production follows the existing managed runtime cache.  Tests and
    operators can select an already-supported internal data directory through
    ``LOCAL_DEV_MCP_DATA_DIR``; the registry path is never treated as a data
    directory and no caller-supplied database path is accepted.
    """
    # An explicit internal data directory remains the operator-controlled
    # source of truth.  Without it, disposable/custom registries get an
    # isolated sibling state directory, but only when that directory is not
    # inside any registered workspace.  A registry stored in a repository
    # therefore still falls back to the managed cache and never creates a DB
    # in the repository itself.
    explicit_data_dir = os.environ.get("LOCAL_DEV_MCP_DATA_DIR")
    if explicit_data_dir:
        # The explicit override is still an internal operator setting, never a
        # model argument.  Refuse a path that resolves inside a registered
        # project so a local test/config mistake cannot put control-plane state
        # next to source or make it part of a repository diff.
        try:
            requested_dir = Path(explicit_data_dir).expanduser().resolve(strict=False)
            document = json.loads(config_path.expanduser().resolve(strict=False).read_text(encoding="utf-8"))
            workspaces = document.get("workspaces", {}) if isinstance(document, dict) else {}
            workspace_paths: list[Path] = []
            if isinstance(workspaces, dict):
                for raw in workspaces.values():
                    if isinstance(raw, dict) and isinstance(raw.get("path"), str):
                        workspace_paths.append(
                            Path(os.path.expandvars(raw["path"])).expanduser().resolve(strict=False)
                        )
            if any(requested_dir == workspace or requested_dir.is_relative_to(workspace) for workspace in workspace_paths):
                return Path.home() / ".cache" / "local-dev-mcp" / "director.sqlite3"
        except (OSError, TypeError, ValueError, json.JSONDecodeError):
            # SqliteDirectorStore still performs the private-directory and
            # symlink checks.  An unreadable config must not turn diagnostics
            # into a new filesystem write target.
            return Path.home() / ".cache" / "local-dev-mcp" / "director.sqlite3"
        return director_db_path()
    try:
        config_resolved = config_path.expanduser().resolve(strict=False)
        parent = config_resolved.parent
        standard_dir = (Path.home() / ".config" / "local-dev-mcp").resolve(strict=False)
        if parent == standard_dir or parent.is_relative_to(standard_dir):
            return director_db_path()
        document = json.loads(config_resolved.read_text(encoding="utf-8"))
        workspaces = document.get("workspaces", {}) if isinstance(document, dict) else {}
        workspace_paths: list[Path] = []
        if isinstance(workspaces, dict):
            for raw in workspaces.values():
                if isinstance(raw, dict) and isinstance(raw.get("path"), str):
                    workspace_paths.append(
                        Path(os.path.expandvars(raw["path"])).expanduser().resolve(strict=False)
                    )
        config_inside_git_repo = any(
            (ancestor / ".git").exists()
            for ancestor in (parent, *parent.parents)
        )
        if not config_inside_git_repo and not any(parent == workspace or parent.is_relative_to(workspace) for workspace in workspace_paths):
            return parent / ".local-dev-mcp-state" / "director.sqlite3"
    except (OSError, TypeError, ValueError, json.JSONDecodeError):
        pass
    return director_db_path()


def _safe_path_text(value: str) -> str:
    return value.replace("\\", "/").strip()


def _is_sensitive_path(raw_path: str) -> bool:
    """Return True for common credentials and private application stores.

    The upstream runtime still owns workspace/symlink containment. This check is
    intentionally a second, deny-by-default layer for names that should not be
    presented to a model even when they happen to be inside an approved repo.
    """

    text = _safe_path_text(raw_path)
    if not text or "\x00" in text:
        return False
    lower = text.lower()
    if lower.startswith(("/", "~/", "\\", "~\\")):
        return True
    parts = [part for part in lower.split("/") if part not in {"", "."}]
    if any(part in SENSITIVE_DIR_NAMES for part in parts):
        return True
    if any(part == ".git" for part in parts):
        return True
    return bool(parts and SENSITIVE_BASENAME_RE.fullmatch(parts[-1]))


def _is_sensitive_absolute(path: Path) -> bool:
    text = _safe_path_text(str(path.resolve(strict=False)))
    return bool(SENSITIVE_ABSOLUTE_RE.search(text) or SENSITIVE_BASENAME_RE.fullmatch(path.name))


def _validate_command_text(command: str) -> None:
    if not command or len(command) > 400 or "\n" in command or "\r" in command:
        raise ToolFailure(
            "COMMAND_PROFILE_INVALID",
            "Configured task commands must be one non-empty line of at most 400 characters.",
            category="validation",
        )


def _validate_metadata_path(raw: object) -> str:
    if not isinstance(raw, str) or not raw or len(raw) > MAX_METADATA_TEXT:
        raise ValueError("metadata path must be a bounded string")
    normalized = _safe_path_text(raw)
    path = Path(normalized)
    if path.is_absolute() or any(part in {"", ".", ".."} for part in path.parts):
        raise ValueError("metadata path must be relative and normalized")
    if _is_sensitive_path(normalized):
        raise ValueError("metadata path is sensitive")
    return normalized


def _parse_project_metadata(raw: object) -> dict[str, Any]:
    if raw in (None, {}):
        return {}
    if not isinstance(raw, dict):
        raise ValueError("metadata must be an object")
    allowed = {"language", "framework", "architecture_ref", "canonical_paths", "task_descriptions", "isolated_development"}
    if set(raw) - allowed:
        raise ValueError("metadata contains unknown keys")
    parsed: dict[str, Any] = {}
    for key in ("language", "framework"):
        value = raw.get(key)
        if value is None:
            continue
        if not isinstance(value, str) or not value.strip() or len(value) > MAX_METADATA_TEXT or SECRET_OUTPUT_RE.search(value):
            raise ValueError(f"metadata.{key} is invalid")
        parsed[key] = value.strip()
    if "architecture_ref" in raw:
        parsed["architecture_ref"] = _validate_metadata_path(raw["architecture_ref"])
    if "canonical_paths" in raw:
        paths = raw["canonical_paths"]
        if not isinstance(paths, list) or not paths or len(paths) > MAX_METADATA_PATHS:
            raise ValueError("metadata.canonical_paths is invalid")
        parsed_paths = [_validate_metadata_path(value) for value in paths]
        if len(set(parsed_paths)) != len(parsed_paths):
            raise ValueError("metadata.canonical_paths contains duplicates")
        parsed["canonical_paths"] = parsed_paths
    if "task_descriptions" in raw:
        descriptions = raw["task_descriptions"]
        if not isinstance(descriptions, dict) or len(descriptions) > MAX_TASK_DESCRIPTIONS:
            raise ValueError("metadata.task_descriptions is invalid")
        parsed_descriptions: dict[str, str] = {}
        for task, description in descriptions.items():
            if task not in TASK_NAMES or not isinstance(description, str) or not description.strip() or len(description) > MAX_METADATA_TEXT or "\n" in description or "\r" in description or SECRET_OUTPUT_RE.search(description):
                raise ValueError("metadata.task_descriptions contains an invalid entry")
            parsed_descriptions[task] = description.strip()
        parsed["task_descriptions"] = parsed_descriptions
    if "isolated_development" in raw:
        policy = raw["isolated_development"]
        if not isinstance(policy, dict):
            raise ValueError("metadata.isolated_development is invalid")
        policy_allowed = {
            "auto_create_sessions",
            "auto_resume_sessions",
            "auto_resume_policy",
            "max_parallel_sessions",
            "allowed_base",
            "allow_workspace_wide",
            "integration_requires_approval",
            "commit_requires_approval",
            "push_requires_approval",
            "verified_auto_commit",
            "auto_approve_safe_local",
            "auto_approve_local_maintenance",
            "manual_approval_ttl_seconds",
            "trusted_session_grant_ttl_seconds",
            "trust_level",
        }
        if set(policy) - policy_allowed:
            raise ValueError("metadata.isolated_development contains unknown keys")
        auto_create = policy.get("auto_create_sessions", False)
        if not isinstance(auto_create, bool):
            raise ValueError("auto_create_sessions must be boolean")
        auto_resume = policy.get("auto_resume_sessions", False)
        if not isinstance(auto_resume, bool):
            raise ValueError("auto_resume_sessions must be boolean")
        auto_resume_policy = policy.get("auto_resume_policy", "same_owner_same_task_safe_local")
        if auto_resume_policy != "same_owner_same_task_safe_local":
            raise ValueError("auto_resume_policy is invalid")
        max_parallel = policy.get("max_parallel_sessions", 1)
        if isinstance(max_parallel, bool) or not isinstance(max_parallel, int) or not 1 <= max_parallel <= MAX_PARALLEL_SESSIONS:
            raise ValueError("max_parallel_sessions is invalid")
        allowed_base = policy.get("allowed_base", "registered_project")
        if allowed_base != "registered_project":
            raise ValueError("allowed_base is invalid")
        for key in ("integration_requires_approval", "commit_requires_approval", "push_requires_approval"):
            if key in policy and not isinstance(policy[key], bool):
                raise ValueError(f"{key} must be boolean")
        if "allow_workspace_wide" in policy and not isinstance(policy["allow_workspace_wide"], bool):
            raise ValueError("allow_workspace_wide must be boolean")
        if "verified_auto_commit" in policy and not isinstance(policy["verified_auto_commit"], bool):
            raise ValueError("verified_auto_commit must be boolean")
        for key in ("auto_approve_safe_local", "auto_approve_local_maintenance"):
            if key in policy and not isinstance(policy[key], bool):
                raise ValueError(f"{key} must be boolean")
        manual_approval_ttl_seconds = policy.get("manual_approval_ttl_seconds", 1800)
        if isinstance(manual_approval_ttl_seconds, bool) or not isinstance(manual_approval_ttl_seconds, int) or not 60 <= manual_approval_ttl_seconds <= 3600:
            raise ValueError("manual_approval_ttl_seconds is invalid")
        trusted_session_grant_ttl_seconds = policy.get("trusted_session_grant_ttl_seconds", 7200)
        if isinstance(trusted_session_grant_ttl_seconds, bool) or not isinstance(trusted_session_grant_ttl_seconds, int) or not 60 <= trusted_session_grant_ttl_seconds <= 7200:
            raise ValueError("trusted_session_grant_ttl_seconds is invalid")
        trust_level = policy.get("trust_level", "standard")
        if trust_level not in {"standard", "trusted_development"}:
            raise ValueError("trust_level is invalid")
        parsed["isolated_development"] = {
            "auto_create_sessions": auto_create,
            "auto_resume_sessions": auto_resume,
            "auto_resume_policy": auto_resume_policy,
            "max_parallel_sessions": max_parallel,
            "allowed_base": allowed_base,
            "allow_workspace_wide": bool(policy.get("allow_workspace_wide", False)),
            "integration_requires_approval": bool(policy.get("integration_requires_approval", True)),
            "commit_requires_approval": bool(policy.get("commit_requires_approval", True)),
            "push_requires_approval": bool(policy.get("push_requires_approval", True)),
            "verified_auto_commit": bool(policy.get("verified_auto_commit", True)),
            "auto_approve_safe_local": bool(policy.get("auto_approve_safe_local", True)),
            "auto_approve_local_maintenance": bool(policy.get("auto_approve_local_maintenance", True)),
            "manual_approval_ttl_seconds": manual_approval_ttl_seconds,
            "trusted_session_grant_ttl_seconds": trusted_session_grant_ttl_seconds,
            "trust_level": trust_level,
        }
    return parsed


def load_registry() -> tuple[Path, dict[str, WorkspaceEntry], list[AllowedRoot], list[dict[str, str]]]:
    path = _config_path()
    if not path.exists():
        roots, root_errors = load_allowed_roots({"version": 1}, Path.home())
        return path, {}, roots, root_errors
    if not path.is_file():
        return path, {}, [], [{"code": "CONFIG_NOT_FILE", "message": str(path)}]
    try:
        document = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        return path, {}, [], [{"code": "CONFIG_INVALID", "message": str(exc)}]
    if not isinstance(document, dict) or document.get("version") != 1:
        return path, {}, [], [{"code": "CONFIG_VERSION_UNSUPPORTED", "message": "version must be 1"}]
    roots, root_errors = load_allowed_roots(document, Path.home())
    raw_workspaces = document.get("workspaces", {})
    if not isinstance(raw_workspaces, dict):
        return path, {}, roots, root_errors + [{"code": "CONFIG_INVALID", "message": "workspaces must be an object"}]

    entries: dict[str, WorkspaceEntry] = {}
    errors: list[dict[str, str]] = list(root_errors)
    for identifier, raw_entry in raw_workspaces.items():
        if not isinstance(identifier, str) or not WORKSPACE_ID_RE.fullmatch(identifier):
            errors.append({"code": "WORKSPACE_ID_INVALID", "message": str(identifier)})
            continue
        if not isinstance(raw_entry, dict):
            errors.append({"code": "WORKSPACE_ENTRY_INVALID", "message": identifier})
            continue
        raw_path = raw_entry.get("path")
        profile = raw_entry.get("profile", "READ_ONLY")
        raw_commands = raw_entry.get("commands", {})
        raw_metadata = raw_entry.get("metadata", {})
        raw_platform = raw_entry.get("platform")
        if isinstance(raw_metadata, dict) and "platform" in raw_metadata:
            if raw_platform not in (None, {}):
                errors.append({"code": "PLATFORM_CONFIG_INVALID", "message": identifier})
                continue
            raw_metadata = dict(raw_metadata)
            raw_platform = raw_metadata.pop("platform")
        if "isolated_development" in raw_entry:
            if not isinstance(raw_metadata, dict):
                raw_metadata = {}
            else:
                raw_metadata = dict(raw_metadata)
            raw_metadata["isolated_development"] = raw_entry["isolated_development"]
        if not isinstance(raw_path, str) or not raw_path:
            errors.append({"code": "WORKSPACE_PATH_INVALID", "message": identifier})
            continue
        if profile not in PROFILE_NAMES:
            errors.append({"code": "PROFILE_INVALID", "message": f"{identifier}: {profile}"})
            continue
        if not isinstance(raw_commands, dict):
            errors.append({"code": "COMMANDS_INVALID", "message": identifier})
            continue
        commands: dict[str, str] = {}
        invalid_commands = False
        for task_name, command in raw_commands.items():
            if task_name not in TASK_NAMES or not isinstance(command, str):
                invalid_commands = True
                continue
            try:
                _validate_command_text(command)
            except ToolFailure:
                invalid_commands = True
                continue
            commands[task_name] = command
        if invalid_commands:
            errors.append({"code": "COMMANDS_INVALID", "message": identifier})
            continue
        try:
            metadata = _parse_project_metadata(raw_metadata)
        except ValueError:
            errors.append({"code": "METADATA_INVALID", "message": identifier})
            continue
        try:
            platform = parse_platform_config(raw_platform)
        except PlatformConfigError:
            errors.append({"code": "PLATFORM_CONFIG_INVALID", "message": identifier})
            continue
        candidate = Path(os.path.expandvars(raw_path)).expanduser()
        if _is_sensitive_absolute(candidate):
            errors.append({"code": "SENSITIVE_WORKSPACE_DENIED", "message": identifier})
            continue
        try:
            resolved = candidate.resolve(strict=False)
        except OSError as exc:
            errors.append({"code": "WORKSPACE_PATH_INVALID", "message": f"{identifier}: {exc}"})
            continue
        entries[identifier] = WorkspaceEntry(identifier, resolved, profile, commands, metadata, platform)
    return path, entries, roots, errors


def _error_payload(code: str, message: str, *, category: str = "policy", details: dict[str, Any] | None = None) -> dict[str, Any]:
    return {
        "ok": False,
        "error": {
            "code": code,
            "message": message,
            "category": category,
            "retryable": False,
            "details": details or {},
        },
    }


def _result(tool_name: str, payload: dict[str, Any], *, error: bool = False) -> dict[str, Any]:
    payload.setdefault("ok", not error)
    return make_tool_result(tool_name, payload, is_error=error or payload.get("ok") is False)


def _redact_output(value: Any) -> Any:
    if isinstance(value, str):
        return SECRET_OUTPUT_RE.sub("[redacted-secret-like-output]", value)
    if isinstance(value, list):
        return [_redact_output(item) for item in value]
    if isinstance(value, dict):
        return {key: _redact_output(item) for key, item in value.items()}
    return value


def _sanitize_payload(payload: Any) -> Any:
    """Remove sensitive path records before structured content reaches the model."""

    if not isinstance(payload, dict):
        return _redact_output(payload)
    result = {key: _redact_output(value) for key, value in payload.items()}
    for key in ("entries", "files", "matches", "affected_files"):
        value = result.get(key)
        if isinstance(value, list):
            safe_items = []
            sensitive_seen = False
            for item in value:
                paths: list[str] = []
                if isinstance(item, dict):
                    for path_key in ("path", "old_path", "original_path"):
                        raw = item.get(path_key)
                        if isinstance(raw, str):
                            paths.append(raw)
                if any(_is_sensitive_path(path) for path in paths):
                    sensitive_seen = True
                    continue
                safe_items.append(item)
            result[key] = safe_items
            if sensitive_seen:
                warnings = result.setdefault("warnings", [])
                if isinstance(warnings, list):
                    warnings.append("sensitive file records omitted by local-dev-mcp")
                if key in {"files", "affected_files"}:
                    result["sensitive_files_omitted"] = True
    if result.get("sensitive_files_omitted"):
        for content_key in ("diff", "content"):
            if isinstance(result.get(content_key), str):
                result[content_key] = "[sensitive file content omitted by local-dev-mcp]"
    return result


def _patch_paths(patch: str) -> list[str]:
    paths: list[str] = []
    for line in patch.splitlines():
        match = PATCH_PATH_RE.match(line)
        if match:
            paths.append(match.group(1).strip())
    return paths


def _unified_patch_path(raw: str, prefix: str) -> str | None:
    value = raw.split("\t", 1)[0].strip()
    if value == "/dev/null":
        return None
    if value.startswith(prefix + "/"):
        value = value[len(prefix) + 1 :]
    return normalize_relative_path(value)


def _unified_to_apply_patch(patch: str) -> str:
    """Adapt a bounded unified diff to coding-tools-mcp's patch envelope."""

    lines = patch.splitlines()
    if lines and lines[0].strip() == "*** Begin Patch":
        return patch

    def is_file_header(index: int) -> bool:
        return (
            index + 1 < len(lines)
            and lines[index].startswith("--- ")
            and lines[index + 1].startswith("+++ ")
        )

    output = ["*** Begin Patch"]
    found = False
    index = 0
    while index < len(lines):
        if not is_file_header(index):
            index += 1
            continue
        old_path = _unified_patch_path(lines[index][4:], "a")
        new_path = _unified_patch_path(lines[index + 1][4:], "b")
        if old_path is None and new_path is None:
            raise ToolFailure(
                "PATCH_FAILED",
                "Unified patch contains a file with no source or destination path.",
                category="validation",
            )
        index += 2
        hunks: list[list[str]] = []
        while index < len(lines) and not is_file_header(index):
            if not lines[index].startswith("@@"):
                index += 1
                continue
            index += 1
            hunk: list[str] = []
            while index < len(lines) and not lines[index].startswith("@@") and not is_file_header(index):
                line = lines[index]
                if not line.startswith("\\"):
                    hunk.append(line)
                index += 1
            hunks.append(hunk)

        if old_path is None:
            assert new_path is not None
            output.append(f"*** Add File: {new_path}")
            for line in (line for hunk in hunks for line in hunk):
                if not line.startswith("+"):
                    raise ToolFailure(
                        "PATCH_FAILED",
                        "Unified add-file lines must start with '+'.",
                        category="validation",
                    )
                output.append(line)
        elif new_path is None:
            output.append(f"*** Delete File: {old_path}")
        else:
            output.append(f"*** Update File: {old_path}")
            if old_path != new_path:
                output.append(f"*** Move to: {new_path}")
            for hunk in hunks:
                output.append("@@")
                output.extend(hunk)
        found = True

    if not found:
        raise ToolFailure(
            "PATCH_FAILED",
            "Patch contains no supported unified file headers.",
            category="validation",
        )
    output.append("*** End Patch")
    return "\n".join(output)


def _custom_tool(name: str, title: str, description: str, schema: dict[str, Any], *, read_only: bool = True, destructive: bool = False, idempotent: bool = False, open_world: bool = False) -> dict[str, Any]:
    return {
        "name": name,
        "title": title,
        "description": description,
        "inputSchema": schema,
        "outputSchema": tool_output_schema(),
        "annotations": {
            "title": title,
            "readOnlyHint": read_only,
            "destructiveHint": destructive,
            "idempotentHint": idempotent,
            "openWorldHint": open_world,
        },
    }


