                read_only = bool(annotations.get("readOnlyHint")) if isinstance(annotations, Mapping) else False
                risk_class = "R0" if read_only else compatibility_risk.decide(tool_name).risk_class.value
                replacement = REGISTRY_REPLACEMENTS.get(tool_name)
