    def _workspace_command_profile_cleanup(self, args: dict[str, Any]) -> dict[str, Any]:
        try:
            result = self._command_profile_cleanup.apply(
                preflight_id=args.get("preflight_id"),
                confirmation=args.get("confirmation"),
            )
        except ProvisioningError as exc:
            raise ToolFailure(exc.code, exc.message, category=exc.category, details=exc.details) from None

        try:
            self.config_path, entries, self.allowed_roots, errors = load_registry()
        except Exception as exc:
            raise ToolFailure(
                "COMMAND_PROFILE_CLEANUP_RECONCILIATION_REQUIRED",
                "Ephemeral command-profile cleanup changed durable config, but runtime registry refresh failed.",
                category="runtime",
                details={
                    "outcome": "reconciliation_required",
                    "side_effect_may_have_applied": True,
                    "config_digest": result.get("config_digest"),
                },
            ) from exc

        workspace_id = result.get("workspace_id")
        registered = entries.get(workspace_id) if isinstance(workspace_id, str) else None
        removed_ids = result.get("removed_profile_ids", [])
        if registered is None or not isinstance(removed_ids, list) or any(
            profile_id in registered.platform.command_profiles for profile_id in removed_ids
        ):
            raise ToolFailure(
                "COMMAND_PROFILE_CLEANUP_RECONCILIATION_REQUIRED",
                "Ephemeral command-profile cleanup changed durable config, but runtime read-back is ambiguous.",
                category="runtime",
                details={
                    "outcome": "reconciliation_required",
                    "side_effect_may_have_applied": True,
                    "config_digest": result.get("config_digest"),
                },
            )
        for key, (entry, runtime) in list(self._workspace_bindings.items()):
            if self._director_logical_workspace_id(entry) != workspace_id:
                continue
            refreshed = replace(entry, platform=registered.platform)
            self._workspace_bindings[key] = (refreshed, runtime)
            if self.current is entry:
                self.current = refreshed
        if self.current is not None and self._director_logical_workspace_id(self.current) == workspace_id:
            self.current = replace(self.current, platform=registered.platform)
        for key in [key for key in self._platform_bundles if key[0] == workspace_id]:
            self._platform_bundles.pop(key, None)
        result["config_errors"] = errors
        return result

