    def _git_commit_preflight(self, args: dict[str, Any]) -> dict[str, Any]:
        self._director_record_usage("git_commit_preflight")
        entry, _runtime = self._require_workspace_args(
            args,
            require_live=False,
            synchronize_active_session=False,
        )
        self._require_profile("DEVELOPMENT", entry=entry)
        if not isinstance(args.get("workspace_id"), str) or not args["workspace_id"]:
            raise ToolFailure("GIT_ARGUMENTS_INVALID", "workspace_id is required for Git routing.", category="validation")
        if set(args) - WORKSPACE_BINDING_ARGUMENTS != {"task_id", "commit_message"}:
            raise ToolFailure("GIT_ARGUMENTS_INVALID", "workspace_id, task_id, and commit_message are required.", category="validation")
        workspace_id = args.get("workspace_id")
        logical_workspace = self._director_logical_workspace_id(entry)
        if workspace_id != logical_workspace:
            raise ToolFailure("GIT_WORKSPACE_MISMATCH", "Git operation must target the selected DEVELOPMENT workspace.", category="permission")
        task = self._git_task_binding(entry, args.get("task_id"))
        try:
            preflight = self._git_write.commit_preflight(
                entry.path,
                workspace_id=logical_workspace,
                working_tree_id=task.working_tree_id,
                task=task,
                commit_message=args.get("commit_message"),
            )
            partial_blockers = {"STAGED_PATH_HAS_UNSTAGED_CHANGES", "WORKTREE_NOT_STAGED_ONLY"}
            blocking_codes = set(preflight.blocking_codes)
            if (
                preflight.status == "blocked"
                and task.evidence_valid
                and "STAGED_PATH_HAS_UNSTAGED_CHANGES" in blocking_codes
                and blocking_codes <= partial_blockers
                and preflight.candidate_paths
            ):
                verified_task = self._git_verified_task_binding(
                    entry,
                    args.get("task_id"),
                    candidate_scope_paths=preflight.candidate_paths,
                )
                self._git_write.invalidate_preflight(preflight.preflight_id)
                preflight = self._git_write.commit_preflight(
                    entry.path,
                    workspace_id=logical_workspace,
                    working_tree_id=verified_task.working_tree_id,
                    task=verified_task,
                    commit_message=args.get("commit_message"),
                )
                task = verified_task
        except GitWriteError as exc:
            raise self._git_tool_failure(exc, operation="commit_preflight") from None
        payload = preflight.as_dict()
        payload["task_binding"] = {
            "task_id": task.task_id,
            "workspace_id": task.workspace_id,
            "working_tree_id": task.working_tree_id,
            "verification_receipt_id": task.verification_receipt_id,
            "security_audit_receipt_id": task.security_audit_receipt_id,
        }
        self._persist_git_closeout(payload, operation="commit_preflight", approval_consumed=False)
        return payload

    def _git_commit(self, args: dict[str, Any]) -> dict[str, Any]:
        self._director_record_usage("git_commit")
        entry, _runtime = self._require_workspace_args(args, require_live=False)
        self._require_profile("DEVELOPMENT", entry=entry)
        expected = {
            "workspace_id", "task_id", "preflight_id", "approval_token", "confirmation", "commit_message",
            "expected_head", "expected_staged_diff_hash", "expected_index_state_hash",
        }
        if not isinstance(args.get("workspace_id"), str) or not args["workspace_id"]:
            raise ToolFailure("GIT_ARGUMENTS_INVALID", "workspace_id is required for Git routing.", category="validation")
        if set(args) - WORKSPACE_BINDING_ARGUMENTS != expected - {"workspace_id"}:
            raise ToolFailure("GIT_ARGUMENTS_INVALID", "git_commit arguments do not match the pinned contract.", category="validation")
        logical_workspace = self._director_logical_workspace_id(entry)
        if args.get("workspace_id") != logical_workspace:
            raise ToolFailure("GIT_WORKSPACE_MISMATCH", "Git operation must target the selected DEVELOPMENT workspace.", category="permission")
        try:
            candidate_paths, partial_stage_adoption = self._git_write.commit_preflight_scope(args["preflight_id"])
        except GitWriteError as exc:
            raise self._git_tool_failure(exc, operation="commit") from None
        recovery_task = self._git_executing_recovery_task_binding(
            entry,
            args.get("task_id"),
            preflight_id=args.get("preflight_id"),
            operation="commit",
        )
        task = recovery_task or (
            self._git_verified_task_binding(
                entry,
                args.get("task_id"),
                candidate_scope_paths=candidate_paths,
            )
            if partial_stage_adoption
            else self._git_task_binding(entry, args.get("task_id"))
        )
        try:
            receipt = self._git_write.commit(
                entry.path,
                workspace_id=logical_workspace,
                working_tree_id=task.working_tree_id,
                task_resolver=(
                    (
                        lambda task_id: self._git_verified_task_binding(
                            entry,
                            task_id,
                            candidate_scope_paths=candidate_paths,
                        )
                    )
                    if partial_stage_adoption
                    else (lambda task_id: self._git_task_binding(entry, task_id))
                ),
                preflight_id=args["preflight_id"],
                approval_token=args["approval_token"],
                confirmation=args["confirmation"],
                commit_message=args["commit_message"],
                expected_head=args["expected_head"],
                expected_staged_diff_hash=args["expected_staged_diff_hash"],
                expected_index_state_hash=args["expected_index_state_hash"],
            )
        except GitWriteError as exc:
            receipt = exc.details.get("receipt") if isinstance(exc.details, dict) else None
            if isinstance(receipt, dict) and isinstance(receipt.get("receipt_id"), str):
                self._persist_git_closeout(receipt, operation="commit", approval_consumed=True)
                self._git_record_receipt(
                    task.task_id,
                    operation="commit",
                    receipt_id=receipt["receipt_id"],
                    receipt_status=str(receipt.get("status", "failed")),
                )
            self._git_write.invalidate_preflight(args["preflight_id"])
            raise self._git_tool_failure(exc, operation="commit") from None
        self._git_record_receipt(task.task_id, operation="commit", receipt_id=receipt.receipt_id)
        self._persist_git_closeout(receipt.as_dict(), operation="commit", approval_consumed=True)
        audit = {
            "receipt_id": receipt.audit_receipt_id,
            "operation": "commit",
            "status": receipt.status,
            "base_revision": receipt.head_before,
            "diff_hash": receipt.staged_diff_hash,
            "external_execution": False,
        }
        return {"status": receipt.status, "receipt": receipt.as_dict(), "audit_receipt": audit, "external_execution": False}

