    def _git_verified_commit(self, args: dict[str, Any]) -> dict[str, Any]:
        self._director_record_usage("git_verified_commit")
        entry, _runtime = self._require_workspace_args(args, require_live=False)
        self._require_profile("DEVELOPMENT", entry=entry)
        expected = {
            "workspace_id",
            "task_id",
            "preflight_id",
            "expected_head",
            "expected_candidate_staged_diff_hash",
            "expected_candidate_index_state_hash",
        }
        if not isinstance(args.get("workspace_id"), str) or not args["workspace_id"]:
            raise ToolFailure("GIT_ARGUMENTS_INVALID", "workspace_id is required for Git routing.", category="validation")
        if set(args) - WORKSPACE_BINDING_ARGUMENTS != expected - {"workspace_id"}:
            raise ToolFailure("GIT_ARGUMENTS_INVALID", "git_verified_commit arguments do not match the pinned contract.", category="validation")
        logical_workspace = self._director_logical_workspace_id(entry)
        if args.get("workspace_id") != logical_workspace:
            raise ToolFailure("GIT_WORKSPACE_MISMATCH", "Git operation must target the selected DEVELOPMENT workspace.", category="permission")
        self._git_verified_policy(logical_workspace)
        basic_task = self._git_task_binding(entry, args.get("task_id"))
        replay = self._git_verified_closeout_replay(
            workspace_id=logical_workspace,
            working_tree_id=basic_task.working_tree_id,
            task_id=basic_task.task_id,
            preflight_id=str(args.get("preflight_id", "")),
            expected_head=str(args.get("expected_head", "")),
            expected_diff_hash=str(args.get("expected_candidate_staged_diff_hash", "")),
            expected_index_hash=str(args.get("expected_candidate_index_state_hash", "")),
        )
        if replay is not None:
            return replay
        recovery_task = self._git_executing_recovery_task_binding(
            entry,
            args.get("task_id"),
            preflight_id=args.get("preflight_id"),
            operation="verified_commit",
        )
        task = recovery_task or self._git_verified_task_binding(entry, args.get("task_id"))
        try:
            receipt = self._git_write.verified_commit(
                entry.path,
                workspace_id=logical_workspace,
                working_tree_id=task.working_tree_id,
                task_resolver=lambda task_id: self._git_verified_task_binding(entry, task_id),
                preflight_id=args["preflight_id"],
                expected_head=args["expected_head"],
                expected_candidate_staged_diff_hash=args["expected_candidate_staged_diff_hash"],
                expected_candidate_index_state_hash=args["expected_candidate_index_state_hash"],
            )
        except GitWriteError as exc:
            raw_receipt = exc.details.get("receipt") if isinstance(exc.details, dict) else None
            if isinstance(raw_receipt, dict) and isinstance(raw_receipt.get("receipt_id"), str):
                self._persist_git_closeout(raw_receipt, operation="verified_commit", approval_consumed=False)
                self._git_record_receipt(
                    task.task_id,
                    operation="verified_commit",
                    receipt_id=raw_receipt["receipt_id"],
                    receipt_status=str(raw_receipt.get("status", "failed")),
                )
            self._git_write.invalidate_preflight(args["preflight_id"])
            raise self._git_tool_failure(exc, operation="verified_commit") from None
        self._git_record_receipt(task.task_id, operation="verified_commit", receipt_id=receipt.receipt_id)
        self._persist_git_closeout(receipt.as_dict(), operation="verified_commit", approval_consumed=False)
        audit = {
            "receipt_id": receipt.audit_receipt_id,
            "operation": "verified_commit",
            "status": receipt.status,
            "base_revision": receipt.head_before,
            "diff_hash": receipt.staged_diff_hash,
            "external_execution": False,
        }
        if receipt.status == "succeeded":
            self._emit_context_checkpoint_best_effort(
                workspace_id=logical_workspace,
                head=self._director_head_for_entry(entry),
                changed_paths=tuple(task.allowed_paths),
                task_id=task.task_id,
                event=AutoCheckpointEvent(
                    kind="verified_commit",
                    outcome="committed",
                    next_action="continue from the verified local commit",
                ),
                verification_receipt_ids=(task.verification_receipt_id,) if task.verification_receipt_id else (),
                security_audit_receipt_ids=(task.security_audit_receipt_id,) if task.security_audit_receipt_id else (),
            )
        return {
            "status": receipt.status,
            "receipt": receipt.as_dict(),
            "audit_receipt": audit,
            "idempotent_replay": False,
            "external_execution": False,
        }

